import "./styles.css";

export default function App() {
  return (
    <div className="App">
      <h1>Event Handling</h1>
      <button
        id="event-button"
        onClick={(e) => console.log(e.target.id)}
        onMouseEnter={() => console.log("Maus ist auf dem Button")}
        onMouseLeave={() => console.log("Maus hat den Button verlassen")}
      >
        Klick mich
      </button>
    </div>
  );
}

